import java.util.Map;

/**
 * Back-of-envelope calculation framework for system design interviews.
 */
public class CapacityEstimator {

    private final long dau;

    public CapacityEstimator(long dailyActiveUsers) {
        this.dau = dailyActiveUsers;
    }

    /** Calculate queries per second from user activity patterns. */
    public Map<String, Object> estimateQps(int actionsPerUserPerDay) {
        long totalDailyRequests = dau * actionsPerUserPerDay;
        double avgQps = totalDailyRequests / 86400.0; // seconds in a day
        double peakQps = avgQps * 3; // assume 3x peak-to-average ratio

        return Map.of(
            "totalDailyRequests", totalDailyRequests,
            "averageQps", Math.round(avgQps * 10) / 10.0,
            "peakQps", Math.round(peakQps * 10) / 10.0,
            "requestsPerSecondPerServer", 1000, // typical web server
            "serversNeeded", Math.max(1, (int) (peakQps / 1000) + 1)
        );
    }

    /** Calculate storage requirements over retention period. */
    public Map<String, Double> estimateStorage(double avgObjectSizeKb,
                                               int objectsPerUserPerDay,
                                               int retentionYears) {
        double dailyNewDataGb = (dau * objectsPerUserPerDay * avgObjectSizeKb)
                / (1024.0 * 1024.0);
        double totalStorageTb = (dailyNewDataGb * 365 * retentionYears) / 1024.0;

        return Map.of(
            "dailyNewDataGb", Math.round(dailyNewDataGb * 100) / 100.0,
            "yearlyDataTb", Math.round(dailyNewDataGb * 365 / 1024 * 100) / 100.0,
            "totalStorageTb", Math.round(totalStorageTb * 100) / 100.0,
            "withReplication3xTb", Math.round(totalStorageTb * 3 * 100) / 100.0
        );
    }

    /** Calculate network bandwidth requirements. */
    public Map<String, Double> estimateBandwidth(double avgResponseSizeKb,
                                                 double peakQps) {
        double bandwidthMbps = (peakQps * avgResponseSizeKb * 8) / 1024.0;

        return Map.of(
            "peakBandwidthMbps", Math.round(bandwidthMbps * 10) / 10.0,
            "peakBandwidthGbps", Math.round(bandwidthMbps / 1024 * 1000) / 1000.0,
            "cdnOffload80PercentGbps", Math.round(bandwidthMbps * 0.2 / 1024 * 1000) / 1000.0
        );
    }

    // Example: Design a URL shortener
    public static void main(String[] args) {
        CapacityEstimator estimator = new CapacityEstimator(100_000_000L);
        Map<String, Object> qps = estimator.estimateQps(5);
        Map<String, Double> storage = estimator.estimateStorage(0.5, 1, 5);

        System.out.printf("Peak QPS: %s%n", qps.get("peakQps"));
        System.out.printf("Total Storage (5yr): %s TB%n", storage.get("totalStorageTb"));
    }
}

